        capability[50][j] = 1

    solver = pywraplp.Solver.CreateSolver('SCIP')
    if not solver:
        print("Failed to create solver")
        return

    select = {}
    for i in I:
        select[i] = solver.BoolVar(f'select[{i}]')

    for j in J:
        constraint_expr = sum(capability[i][j] * select[i] for i in I)
        solver.Add(constraint_expr >= 1, f'cover_req_{j}')

    objective = solver.Sum(cost[i] * select[i] for i in I)
    solver.Minimize(objective)

    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL or status == pywraplp.Solver.FEASIBLE:
        selected_equipment = [i for i in I if select[i].solution_value() > 0.5]
        total_cost = int(solver.Objective().Value())
        print(json.dumps({
            "selected_equipment": selected_equipment,
            "total_equipment_cost": total_cost
        }))
    else:
        print(json.dumps({
            "selected_equipment": [],
            "total_equipment_cost": 0
        }))

